fields.InputDefinition:
{
  "goal": "Using the application switcher dropdown next to the logo (NOT the Ctrl+K search box), open the Communication app, then open its New Communication (New Message) section. Then walk these sections IN ORDER, and as you arrive at each set \"checkpointReached\" to the exact checkpoint name shown: (1) channel-cascade — in the Message panel open the 'Channel' dropdown and confirm it renders and is interactive; if channels are listed, select one and watch the 'Message type' dropdown react (appear/update for that channel, or stay correctly hidden if the channel has no message types); (2) send-gating — observe the 'Preview Audience' and 'Send' buttons in the header and confirm both are DISABLED in the initial empty state and stay disabled while required inputs (channel, audience, recipient field, from-address) are missing (you may type into From/Subject/Body and confirm Send stays disabled; do NOT send); (3) audience-picker — in the 'Audience' panel on the right, confirm the audience-source picker renders with selectable source-type options (List / saved View / ad-hoc filter), and if you select a source confirm a 'Recipient field' text input appears beneath the picker. Keep going until every section has been visited. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "channel-cascade",
      "instruction": "Channel → Message type cascade",
      "visualCriteria": [
        "The Channel dropdown renders and can be opened, and after choosing a channel (if any exist) the Message type dropdown reflects that channel — it appears/updates, or is correctly absent when the channel has no types"
      ]
    },
    {
      "name": "send-gating",
      "instruction": "Preview/Send disabled until valid",
      "visualCriteria": [
        "The Preview Audience and Send buttons render and are disabled in the initial empty state, and they stay disabled while required inputs (channel / audience / recipient field) are absent"
      ]
    },
    {
      "name": "audience-picker",
      "instruction": "audience-source picker + recipient field",
      "visualCriteria": [
        "The Audience panel renders an audience-source picker with selectable source-type options (List / View / ad-hoc), and choosing a source reveals the 'Recipient field' input (or the picker clearly renders its options even if no source is chosen)"
      ]
    }
  ]
}
